### modified_wrapper.sv
1: // AI-authored, publicly documented simulation-only one-bit fault demonstration.
2: // No recovered-core edits, secret access, obfuscation, or board pin claim.
3: module protocol_dut(
4:     input wire SCK, RST_N, MOSI, NORM_CS_N, START, ENC_DEC,
5:     output wire MISO, BUSY, ICE_LED
6: );
7:     localparam [31:0] DEMO_WORD = 32'hC5A02026;
8:     wire raw_miso;
9:     reg [31:0] ingress_word;
10:     reg [5:0] ingress_count, read_count;
11:     reg frame_complete, start_q, read_pending, fault_active;
12: 
13:     chip recovered(
14:         .io_9_31_1(SCK), .io_13_31_1(RST_N), .io_16_31_0(MOSI),
15:         .io_17_31_0(NORM_CS_N), .io_18_31_1(START), .io_19_31_1(ENC_DEC),
16:         .io_16_31_1(raw_miso), .io_8_31_1(BUSY), .io_19_31_0(ICE_LED)
17:     );
18: 
19:     // Count==1 AFTER the first extraction edge: invert only sampled bit31.
20:     assign MISO = raw_miso ^ (fault_active && !NORM_CS_N && read_count == 6'd1);
21: 
22:     // CS deassertion delimits a frame even when no SCK edge occurs while CS is high.
23:     // Only this counter uses CS as an asynchronous clear; RST_N remains synchronous.
24:     always @(posedge SCK or posedge NORM_CS_N) begin
25:         if (NORM_CS_N)
26:             ingress_count <= 6'd0;
27:         else if (!RST_N)
28:             ingress_count <= 6'd0;
29:         else if (!read_pending && ingress_count < 6'd33)
30:             ingress_count <= ingress_count + 6'd1;
31:     end
32: 
33:     always @(posedge SCK) begin
34:         if (!RST_N) begin
35:             ingress_word <= 32'd0;
36:             read_count <= 6'd0;
37:             frame_complete <= 1'b0;
38:             start_q <= 1'b0;
39:             read_pending <= 1'b0;
40:             fault_active <= 1'b0;
41:         end else begin
42:             start_q <= START;
43:             if (!NORM_CS_N && !read_pending) begin
44:                 ingress_word <= {ingress_word[30:0], MOSI};
45:                 if (ingress_count == 6'd31)
46:                     frame_complete <= 1'b1;
47:                 else if (ingress_count == 6'd0 || ingress_count >= 6'd32)
48:                     frame_complete <= 1'b0;
49:             end
50: 
51:             if (START && !start_q && NORM_CS_N) begin
52:                 fault_active <= frame_complete && !ENC_DEC && ingress_word == DEMO_WORD;
53:                 frame_complete <= 1'b0; // A START consumes the completed ingress.
54:                 read_pending <= 1'b1;
55:                 read_count <= 6'd0;
56:             end else if (read_pending && !NORM_CS_N) begin
57:                 read_count <= read_count + 6'd1;
58:                 if (read_count == 6'd31) begin
59:                     read_pending <= 1'b0;
60:                     fault_active <= 1'b0;
61:                 end
62:             end
63:             // Extraction MOSI is deliberately excluded from ingress qualification.
64:         end
65:     end
66: endmodule

### demonstration_tb.sv
1: `timescale 1ps/1ps
2: // AI-authored independent pin-level oracle: expected faults come from test cases,
3: // never from reading the modified DUT's internal trigger state.
4: module demo_tb;
5:   reg SCK=0,RST_N=1,MOSI=0,NORM_CS_N=1,START=0,ENC_DEC=0;
6:   wire MISO,BUSY,ICE_LED,ref_miso,ref_busy,ref_led;
7:   protocol_dut dut(.*);
8:   chip reference_core(.io_9_31_1(SCK),.io_13_31_1(RST_N),.io_16_31_0(MOSI),
9:     .io_17_31_0(NORM_CS_N),.io_18_31_1(START),.io_19_31_1(ENC_DEC),
10:     .io_16_31_1(ref_miso),.io_8_31_1(ref_busy),.io_19_31_0(ref_led));
11:   localparam [31:0] P=32'h59c359c3,C=32'h9cd84392,T=32'hc5a02026;
12:   integer checks=0,failures=0,reads=0,fault_reads=0,normal_reads=0;
13:   integer expected_flips=0,observed_flips=0,known_operations=0,fd,j,a,b;
14:   reg sampled_m,sampled_r,pause_mode=0;
15:   reg [31:0] discard_m,discard_r,out_m,out_r,word_value;
16:   string case_name="initial",phase="idle";
17: 
18:   task check(input string label,input bit good);
19:     begin checks=checks+1;if(!good)begin failures=failures+1;
20:       $display("FAIL case=%s phase=%s check=%s time=%0t",case_name,phase,label,$time);
21:     end end
22:   endtask
23:   task pulse(input bit expected_flip);
24:     reg [5:0] held;
25:     begin
26:       #500000;SCK=1;#1000;
27:       sampled_m=MISO;sampled_r=ref_miso;
28:       check("MISO_RELATION",MISO===(ref_miso ^ expected_flip));
29:       check("BUSY_EQUAL",BUSY===ref_busy);check("LED_EQUAL",ICE_LED===ref_led);
30:       expected_flips=expected_flips+expected_flip;
31:       if((MISO ^ ref_miso)===1'b1)observed_flips=observed_flips+1;
32:       $fdisplay(fd,"%0t,%s,%s,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b",
33:         $time,case_name,phase,SCK,RST_N,MOSI,NORM_CS_N,START,ENC_DEC,
34:         MISO,ref_miso,BUSY,ref_busy,ICE_LED,ref_led,expected_flip);
35:       held={MISO,BUSY,ICE_LED,ref_miso,ref_busy,ref_led};
36:       #498999;check("HIGH_HOLD",held==={MISO,BUSY,ICE_LED,ref_miso,ref_busy,ref_led});
37:       SCK=0;#1;
38:     end
39:   endtask
40:   task tick;begin pulse(0);end endtask
41:   task reset_idle;
42:     begin phase="reset";NORM_CS_N=1;START=0;RST_N=0;tick();RST_N=1;tick();end
43:   endtask
44:   task paused_hold;
45:     reg [5:0] held;
46:     begin held={MISO,BUSY,ICE_LED,ref_miso,ref_busy,ref_led};#5000000;
47:       check("NO_CLOCK_HOLD",held==={MISO,BUSY,ICE_LED,ref_miso,ref_busy,ref_led});end
48:   endtask
49:   task transfer(input reg [31:0] tx,input integer bits_n,input bit is_read,input bit fault,
50:                 output reg [31:0] rx_m,output reg [31:0] rx_r);
51:     integer k;
52:     begin
53:       rx_m=0;rx_r=0;NORM_CS_N=0;
54:       for(k=bits_n-1;k>=0;k=k-1)begin
55:         MOSI=tx[k%32];pulse(is_read && fault && k==bits_n-1);
56:         rx_m={rx_m[30:0],sampled_m};rx_r={rx_r[30:0],sampled_r};
57:         if(is_read)check("READ_BITS_KNOWN",
58:           (sampled_m===1'b0 || sampled_m===1'b1) && (sampled_r===1'b0 || sampled_r===1'b1));
59:         if(pause_mode && (k==31 || k==16))paused_hold();
60:       end
61:       NORM_CS_N=1;#1;check("CS_HIGH_PASSTHROUGH",MISO===ref_miso);
62:     end
63:   endtask
64:   task launch;
65:     begin phase="launch";START=1;tick();START=0;phase="completion";repeat(7)tick();
66:       check("COMPLETE_BUSY_LOW",BUSY===1'b0 && ref_busy===1'b0);end
67:   endtask
68:   task extract(input reg [31:0] tx,input bit fault,output reg [31:0] rx_m,output reg [31:0] rx_r);
69:     begin
70:       phase="extract";transfer(tx,32,1,fault,rx_m,rx_r);reads=reads+1;
71:       if(fault)fault_reads=fault_reads+1;else normal_reads=normal_reads+1;
72:       check("WORD_RELATION",rx_m===(rx_r ^ (fault?32'h80000000:32'h0)));
73:       $display("RESULT case=%s mode=%0d baseline=%08h modified=%08h xor=%08h expected_fault=%0d",
74:         case_name,ENC_DEC,rx_r,rx_m,rx_r^rx_m,fault);
75:     end
76:   endtask
77:   task operation(input bit mode,input reg [31:0] tx,input bit fault,input bit known_value,
78:                  input reg [31:0] expected,input integer idle_clocks);
79:     reg [31:0] m,r;
80:     begin
81:       ENC_DEC=mode;phase="ingest";transfer(tx,32,0,0,discard_m,discard_r);
82:       phase="idle_gap";repeat(idle_clocks)tick();launch();extract(0,fault,m,r);
83:       if(known_value)begin known_operations=known_operations+1;
84:         check("ORIGINAL_REFERENCE_VALUE",r===expected);
85:         check("ORIGINAL_MODIFIED_VALUE",m===(expected ^ (fault?32'h80000000:32'h0)));
86:       end
87:     end
88:   endtask
89:   initial begin #1000000000000;$fatal(1,"watchdog");end
90:   initial begin
91:     fd=$fopen("demo_trace.csv","w");if(fd==0)$fatal(1,"cannot open trace");
92:     $fdisplay(fd,"time_ps,case,phase,SCK,RST_N,MOSI,CS_N,START,ENC_DEC,MISO,REF_MISO,BUSY,REF_BUSY,LED,REF_LED,expected_flip");
93:     $dumpfile("demo_pins.vcd");$dumpvars(0,SCK,RST_N,MOSI,NORM_CS_N,START,ENC_DEC,MISO,ref_miso,BUSY,ref_busy,ICE_LED,ref_led);
94:     // All four mode pairs, no reset between the two operations in each pair.
95:     for(a=0;a<2;a=a+1)for(b=0;b<2;b=b+1)begin
96:       case_name=$sformatf("original_pair_%0d%0d",a,b);reset_idle();
97:       operation(a,a?C:P,0,1,a?P:C,0);operation(b,b?C:P,0,1,b?P:C,0);
98:     end
99:     case_name="ordinary_sequence";reset_idle();
100:     for(j=0;j<64;j=j+1)begin
101:       word_value=(32'h9e3779b9*j)+32'h12345678;
102:       if(word_value==T)word_value=word_value^1;
103:       operation(j%2,word_value,0,0,0,j%3);
104:     end
105:     for(j=0;j<32;j=j+1)begin
106:       case_name=$sformatf("one_bit_neighbor_%0d",j);operation(0,T^(32'h1<<j),0,0,0,0);
107:     end
108:     case_name="same_word_other_mode";operation(1,T,0,0,0,3);
109:     case_name="trigger_no_gap";operation(0,T,1,0,0,0);
110:     case_name="normal_after_trigger";operation(0,P,0,1,C,0);
111:     case_name="trigger_idle_and_pauses";pause_mode=1;operation(0,T,1,0,0,3);pause_mode=0;
112:     case_name="second_extraction_without_start";extract(0,0,out_m,out_r);
113:     case_name="consecutive_trigger_a";operation(0,T,1,0,0,0);
114:     case_name="consecutive_trigger_b";operation(0,T,1,0,0,0);
115:     // A readout carrying the public word must not qualify another START.
116:     case_name="extraction_not_ingress";reset_idle();ENC_DEC=0;
117:     phase="ingest";transfer(T,32,0,0,discard_m,discard_r);launch();extract(T,1,out_m,out_r);
118:     case_name="no_rearm_from_readout";launch();extract(0,0,out_m,out_r);
119:     // Malformed lengths cannot qualify even when the final 32 bits equal T.
120:     for(j=0;j<3;j=j+1)begin
121:       case_name=$sformatf("bad_length_%0d",j==0?31:(j==1?33:67));reset_idle();ENC_DEC=0;
122:       phase="seed_known_state";transfer(0,32,0,0,discard_m,discard_r);tick();
123:       phase="malformed_ingress";transfer(T,j==0?31:(j==1?33:67),0,0,discard_m,discard_r);
124:       launch();extract(0,0,out_m,out_r);
125:     end
126:     case_name="reset_cancels_pending";reset_idle();ENC_DEC=0;
127:     phase="ingest";transfer(T,32,0,0,discard_m,discard_r);launch();reset_idle();extract(0,0,out_m,out_r);
128:     case_name="reset_during_extraction";reset_idle();ENC_DEC=0;
129:     phase="ingest";transfer(T,32,0,0,discard_m,discard_r);launch();
130:     phase="partial_extract";NORM_CS_N=0;MOSI=0;
131:     for(j=0;j<5;j=j+1)pulse(j==0);
132:     NORM_CS_N=1;#1;reset_idle();extract(0,0,out_m,out_r);
133:     case_name="held_start";reset_idle();ENC_DEC=0;
134:     phase="ingest";transfer(T,32,0,0,discard_m,discard_r);
135:     phase="held_start";START=1;repeat(3)tick();START=0;repeat(7)tick();extract(0,1,out_m,out_r);
136:     case_name="start_while_selected_ignored";reset_idle();ENC_DEC=0;START=1;
137:     phase="invalid_start_ingress";transfer(T,32,0,0,discard_m,discard_r);START=0;tick();
138:     case_name="final_normal_after_reset";reset_idle();operation(1,C,0,1,P,0);
139:     check("FAULT_COUNT_MATCH",expected_flips==observed_flips);
140:     check("COVERAGE",normal_reads>=100 && fault_reads==6 && known_operations==10);
141:     $fclose(fd);
142:     $display("COMPLETE checks=%0d failures=%0d reads=%0d normal_reads=%0d fault_reads=%0d known_operations=%0d expected_flips=%0d observed_flips=%0d",
143:       checks,failures,reads,normal_reads,fault_reads,known_operations,expected_flips,observed_flips);
144:     if(failures)$fatal(1,"demonstration checks failed");$finish;
145:   end
146: endmodule

